from pathlib import Path
import json,base64,zlib,hashlib
base=Path('/home/uwb_student00/ahls/new_BSP'); evidence=base/'qualification/goal-initial-preflight'; backup=evidence/'pre-gate-deployment-backup'
assert not (base/'work_ia840f_ipgen_01').exists()
assert not (base/'work_ia840f_ipgen_01.authorization-claim').exists()
assert not backup.exists(), 'deployment already attempted'
files=json.loads(zlib.decompress(base64.b64decode('')))
receipt=[]
for rel,f in files.items():
 p=base/rel; assert p.resolve().is_relative_to(base)
 assert hashlib.sha256(f['content'].encode()).hexdigest()==f['sha256']
 old=hashlib.sha256(p.read_bytes()).hexdigest() if p.exists() else None
 if p.exists():
  b=backup/rel;b.parent.mkdir(parents=True,exist_ok=True);b.write_bytes(p.read_bytes())
 p.parent.mkdir(parents=True,exist_ok=True);p.write_text(f['content']);p.chmod(f['mode'])
 actual=hashlib.sha256(p.read_bytes()).hexdigest();assert actual==f['sha256']
 receipt.append({'path':rel,'before_sha256':old,'after_sha256':actual})
(evidence/'reviewed-gate-deployment.json').write_text(json.dumps(receipt,indent=2))
print('GATE_DEPLOYED_VERIFIED',len(receipt))
